<?php
declare(strict_types=1);
require_once __DIR__.'/../business/config/customer_membership.php';
require_once __DIR__.'/pwa_step24.php';
$error=null;$settings=[];$customerCtx=['scope'=>'guest','is_member'=>false];$signed=null;
try{$pdo=ps23_db();cm_ensure($pdo);$ctx=ps23_context($pdo);$settings=ps23_settings($pdo,$ctx['organization_id']);$customerCtx=cm_customer_context($pdo,$ctx['organization_id']);$signed=$customerCtx['user']??null;}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html lang="en-IN"><head><?php s24_head('Checkout Request - Healthcare Wellness Club','Submit your product cart to Healthcare Wellness Club for final review and confirmation.','checkout.php','noindex,nofollow,noarchive');?><style>.pricing-banner{margin-bottom:12px;padding:12px 14px;border:1px solid #dce8e1;border-radius:13px;background:linear-gradient(135deg,#f3fbf6,#fffaf0);font-size:.72rem;color:#5e7468}.pricing-banner b{color:#173c2c}.summary-old{text-decoration:line-through;color:#899790;font-size:.72rem}</style></head><body><a class="skip-link" href="#main-content">Skip to main content</a><header class="store-top"><div class="store-bar"><a class="store-brand" href="index.php"><img src="../img/logo.png" alt="Healthcare Wellness Club" width="42" height="42"><span><strong>Healthcare Wellness Club</strong><small><?=!empty($customerCtx['is_member'])?'Club Member Checkout':'Order Request Checkout'?></small></span></a><nav class="store-actions" aria-label="Checkout actions"><?php if($signed):?><a class="store-btn" href="../customer_portal.php">My Portal</a><?php endif;?><a class="store-btn" href="cart.php">Back to Cart</a><a class="store-btn primary" href="index.php">Products</a></nav></div></header><main class="store-shell" id="main-content"><section class="store-hero" aria-labelledby="checkout-title"><div class="store-kicker">SECURE ORDER REQUEST</div><h1 id="checkout-title"><?=!empty($customerCtx['is_member'])?'Your assigned Club Member price is verified again before submission.':'Send your cart to the club for final confirmation.'?></h1><p>The server recalculates every product ID, quantity, pricing tier, eligible offer, VP total and delivery charge. Browser totals are never accepted as the final request amount.</p></section><?php if($error):?><div class="notice bad" role="alert"><?=ps23_h($error)?></div><?php endif;?><section class="two-col" style="margin-top:16px"><article class="card"><h2>Your details</h2><?php if($signed):?><div class="pricing-banner"><b>Signed in as <?=ps23_h($signed['full_name'])?>.</b> For account safety, checkout email/mobile must match this Customer login.</div><?php endif;?><form id="checkoutForm" method="post" action="submit.php"><input type="hidden" name="cart_json" id="cart_json"><input type="hidden" name="started_at" id="started_at"><div class="hp-field" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="checkout-grid"><label for="customerName">Name<input class="store-input" id="customerName" name="name" maxlength="190" autocomplete="name" value="<?=ps23_h($signed['full_name']??'')?>" required></label><label for="customerMobile">Mobile<input class="store-input" id="customerMobile" name="mobile" maxlength="40" inputmode="tel" autocomplete="tel" value="<?=ps23_h($signed['mobile']??'')?>" required></label><label class="full" for="customerEmail">Email<?= $signed?'':' (optional)' ?><input class="store-input" id="customerEmail" type="email" name="email" maxlength="190" inputmode="email" autocomplete="email" value="<?=ps23_h($signed['email']??'')?>" <?=$signed?'required':''?>></label><label for="delivery_mode">Delivery mode<select class="store-select" name="delivery_mode" id="delivery_mode"><option value="club_pickup">Club Pickup</option><option value="home_delivery">Home Delivery / Ecom Drop Point</option></select></label><label for="postalCode">Postal code (optional)<input class="store-input" id="postalCode" name="postal_code" maxlength="20" inputmode="numeric" autocomplete="postal-code"></label><label class="full" id="addressLabel" for="address" hidden>Delivery address<textarea class="store-textarea" name="address" id="address" rows="3" maxlength="1500" autocomplete="street-address"></textarea></label><label class="full" for="orderNote">Note (optional)<textarea class="store-textarea" id="orderNote" name="note" rows="3" maxlength="2000" placeholder="Product/order note only. Do not send private medical records."></textarea></label><label class="full consent-row" for="consent"><input type="checkbox" id="consent" name="consent" value="1" required><span>I agree that Healthcare Wellness Club may contact me about this product order request.</span></label></div><div id="formAlert" role="status" aria-live="polite" aria-atomic="true"></div><button class="store-btn primary" id="submitBtn" type="submit" style="width:100%;margin-top:12px">Send Order Request</button></form></article><aside class="card"><h2>Server-verified Preview</h2><div id="pricingMode" class="pricing-banner" hidden></div><div id="checkoutItems" aria-live="polite"></div><div class="summary-line"><span>MRP Total</span><strong id="mrp">₹0.00</strong></div><div class="summary-line"><span>Your Product Total</span><strong id="customerTotal">₹0.00</strong></div><div class="summary-line"><span>Total Discount</span><strong id="discount">₹0.00</strong></div><div class="summary-line"><span>Total VP</span><strong id="vp">0</strong></div><div class="summary-line"><span>Delivery</span><strong id="delivery">₹0.00</strong></div><div class="summary-line grand"><span>Estimated Total</span><strong id="grand">₹0.00</strong></div><div class="notice warn">Applicable Home Delivery: total VP below 100 = ₹118 delivery charge. Total VP 100 or more = ₹0. Club Pickup = ₹0.</div><div class="notice">Payment mode: <b><?=ps23_h(strtoupper((string)($settings['payment_mode']??'review_only')))?></b>. No online payment is collected now.</div></aside></section></main><footer class="store-footer">Your request becomes a final sale only after Business OS review. <span class="network-badge" data-network-status role="status" aria-live="polite">Online</span></footer><script src="<?=s24_h(s24_asset('store.js'))?>" defer></script><script>
document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('checkoutForm');const mode=document.getElementById('delivery_mode');const money=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(Number(value)||0);const esc=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));let previewSeq=0,lastQuote=null;
async function getQuote(cart){const body=new FormData();body.set('cart_json',JSON.stringify(cart));body.set('delivery_mode',mode.value);const response=await fetch('quote.php',{method:'POST',body,headers:{Accept:'application/json'}});const data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.message||'Price quote could not be calculated.');return data;}
async function preview(){const seq=++previewSeq;const cart=hwcCart();document.getElementById('cart_json').value=JSON.stringify(cart);const addressLabel=document.getElementById('addressLabel');const address=document.getElementById('address');const needsAddress=mode.value==='home_delivery';addressLabel.hidden=!needsAddress;address.required=needsAddress;if(!cart.length){lastQuote=null;document.getElementById('checkoutItems').innerHTML='<div class="empty">Your cart is empty.</div>';return false}try{const data=await getQuote(cart);if(seq!==previewSeq)return false;lastQuote=data;const box=document.getElementById('checkoutItems');box.innerHTML='';for(const item of data.items){const div=document.createElement('div');div.className='summary-line';const label=item.unit_price<item.mrp?`${item.qty} × ${esc(item.name)}<br><small class="summary-old">MRP ${money(item.line_mrp)}</small>`:`${item.qty} × ${esc(item.name)}`;div.innerHTML=`<span>${label}</span><strong>${money(item.line_price)}</strong>`;box.appendChild(div)}document.getElementById('mrp').textContent=money(data.subtotal_mrp);document.getElementById('customerTotal').textContent=money(data.subtotal_customer);document.getElementById('discount').textContent=money(data.discount_amount);document.getElementById('vp').textContent=Number(data.total_vp).toFixed(3).replace(/0+$/,'').replace(/\.$/,'');document.getElementById('delivery').textContent=money(data.delivery_charge);document.getElementById('grand').textContent=money(data.estimated_total);const pricing=document.getElementById('pricingMode');pricing.hidden=false;pricing.innerHTML=data.is_member?`<b>${esc(data.discount_label_code||'Club Member')} pricing active.</b> Server verified exact assigned tier and eligible offers.`:`<b>Regular customer pricing.</b> MRP and eligible configured offers are server verified.`;return true}catch(error){if(seq===previewSeq){lastQuote=null;document.getElementById('formAlert').innerHTML='<div class="notice bad">'+esc(error.message||'Price quote could not be calculated.')+'</div>'}return false}}
mode.addEventListener('change',preview);document.getElementById('started_at').value=String(Date.now());preview();form.addEventListener('submit',async event=>{event.preventDefault();const alertBox=document.getElementById('formAlert');if(!navigator.onLine){alertBox.innerHTML='<div class="notice bad">Internet connection is required to submit an order request.</div>';return}if(!await preview()){alertBox.innerHTML='<div class="notice bad">Your cart is empty or the current price quote is unavailable.</div>';return}if(!form.reportValidity())return;const button=document.getElementById('submitBtn');button.disabled=true;button.textContent='Submitting…';try{const response=await fetch('submit.php',{method:'POST',body:new FormData(form),headers:{Accept:'application/json'}});const data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.message||'Order request could not be submitted.');if(!data.order_code||!data.status_token){alertBox.innerHTML='<div class="notice">Thanks. Your request has been received.</div>';hwcClear();return}hwcClear();const statusForm=document.createElement('form');statusForm.method='post';statusForm.action='status.php';for(const [key,value] of Object.entries({code:data.order_code,token:data.status_token,created:'1'})){const input=document.createElement('input');input.type='hidden';input.name=key;input.value=value;statusForm.appendChild(input)}document.body.appendChild(statusForm);statusForm.submit()}catch(error){alertBox.innerHTML='<div class="notice bad">'+esc(error.message||'Something went wrong.')+'</div>'}finally{button.disabled=false;button.textContent='Send Order Request'}})});
</script>
<script src="../js/site.js"></script>
</body></html>
